  FT["PH-H2326"] = {"id":"PH-H2326","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2598_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Barrio of Kaga-Olas in the Municipality of Matanao, Province of Davao, to Swerte","orig":"An Act Changing the Name of the Barrio of Kaga-Olas in the Municipality of Matanao, Province of Davao, to Swerte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2598","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2598_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2326-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Kaga-olas in the Municipality of Matanao, Province of Davao, is changed to Swerte."}},{"id":"PH-H2326-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
  FT["PH-H2327"] = {"id":"PH-H2327","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2599_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of Certain Barrios in the Municipality of Goa, Province of Camarines Sur","orig":"An Act Changing the Names of Certain Barrios in the Municipality of Goa, Province of Camarines Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2599","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2599_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2327-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The names of the barrios of Balaynan and Aroro in the Municipality of Goa, Province of Camarines Sur, are changed to San Rafael and San Pedro, respectively."}},{"id":"PH-H2327-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
  FT["PH-H2328"] = {"id":"PH-H2328","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2600_1959.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Certain Barrios in the Municipalities of Malitbog and Sogod, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipalities of Malitbog and Sogod, Province of Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2600","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2600_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2328-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios and streets in the Municipality of Malitbog, Province of Leyte, are hereby constituted into barrios:\na. Sitios Cabongbongan and Cantamoac into a barrio to be known as Barrio Cantamoac;\nb. Sitios Lambunao and Guinabunan into a barrio to be known as Barrio Lambunao;\nc. Sitios Caraatan and Manislag into a barrio to be known as Barrio Caraatan;\nd. Sitios Calicot and Pacil into a barrio to be known as Barrio Pacil;\ne. Rizal Avenue, F. Escano Street and San Antonio Street into a barrio to be known as Barrio San Antonio;\nf. Quezon Avenue and Cabul-anonan into a barrio to be known as Barrio Cabul-anonan;\ng. Sitios Sabang, Abgao and Gutos into a barrio to be known as Barrio Abgao;\nh. Sitios Sangahon, Maningning, Comonohan and Bagacay into a barrio to be known as Barrio Sangahon;\ni. Sitios Aliali, Bunga, Hinatigan and part of sitios Jubas into a barrio to be known as Barrio Aliali;\nj. Sitios Tigbawan South, Pericohon and Cansigna into a barrio to be known as Barrio Tigbawan Sur;\nk. Sitio Tigbawan Norte and part of Sitio Jubac into a barrio to be known as Barrio Tigbawan Norte;\nl. Sitios Timba and Iba into a barrio to be known as Barrio Iba.\nm. Sitios Maujo and Juangon into a barrio to be known as Barrio Maujo;\nn. Sitios Hugpa, Panaytayon, Hinagtikan, Hahangin, Hagwason, Pong-on and Bod into a barrio to be known as Barrio Rizal;\no. Sitio Cabascan into a barrio to be known as Barrio Cabascan;\np. Sitios Pañas, Tinago and Higosoan into a barrio to be known as Barrio Cambite;\nq. Sitios Cardeling, Lawan Biasong and Maanyog into a barrio to be known as Barrio Maanyag;\nr. Sitios Carnaga, Pong-ong, Maugob and Bacuel into a barrio to be known as Barrio Carnaga;\ns. Sitios Buenavista, Mapgap, Tewis and Anahawan into a barrio to be known as Barrio Anahawan;\nt. Sitios Camorosan, Kapartidosan and Cawayan into a barrio to be known as Barrio Cawayan; and\nu. Sitios Maslog, Taginoling and Calayogan into a barrio to be known as Barrio Maslog."}},{"id":"PH-H2328-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitio of Punong in the Municipality of Sogod, Province of Leyte, is hereby converted into a barrio to be known as Barrio La Purisima Concepcion."}},{"id":"PH-H2328-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
  FT["PH-H2329"] = {"id":"PH-H2329","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2601_1959.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Creating Barrios in Certain Municipalities of the Province of Rizal","orig":"An Act Creating Barrios in Certain Municipalities of the Province of Rizal"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2601","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2601_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2329-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Caniogan, Calero and Lunang in the Municipality of Morong, Province of Rizal, are constituted into a distinct and independent barrio of said municipality to be known as the barrio of Caniogan."}},{"id":"PH-H2329-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Barangka, Parang and Nangka in the Municipality of Marikina, same province, are converted into barrios of the said municipality to be known as the barrios of Barangka, Parang and Nangka, respectively."}},{"id":"PH-H2329-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sitio of Manggahan in the Municipality of Pasig, same province, is converted into a barrio of said municipality to be known as the barrio of Manggahan."}},{"id":"PH-H2329-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
