  FT["PH-H2331"] = {"id":"PH-H2331","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2603_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立San Remigio市","en":"An Act Creating the Barrio of Dapdap in the Municipality of San Remigio, Province of Cebu","orig":"An Act Creating the Barrio of Dapdap in the Municipality of San Remigio, Province of Cebu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2603","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2603_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2331-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Dapdap in the Municipality of San Remigio, Province of Cebu, is converted into a barrio of the said Municipality to be known as the barrio of Dapdap."}},{"id":"PH-H2331-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
  FT["PH-H2332"] = {"id":"PH-H2332","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2604_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Names of a Barrio and of Sitios in the Municipality of Polanco, Province of Zamboanga del Norte","orig":"An Act Changing the Names of a Barrio and of Sitios in the Municipality of Polanco, Province of Zamboanga del Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2604","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2604_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2332-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Loboc in the Municipality of Polanco, Province of Zamboanga del Norte, is changed to San Miguel, and the names of the sitios of Lantoy and Biga-an in the same municipality are changed to Sto. Niño and Mabuhay, respectively."}},{"id":"PH-H2332-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 21, 1959."}}],"pack":"ph-p33"};
